template:
@php
    // The fields of a form, every one of the block's list in every state it names: the same field
    // empty, filled, with the server's error and disabled, one column under another. Names are
    // "<state>-<n>.<name>" — dotted, as a module writes them — so a group of radios in one state
    // is not the same group as in the next, and two blocks on a page stay apart.
    $set = \WebxUi\Widgets\Facades\Widgets::sequence('showcase-fields');
    $shownStates = array_values(array_filter(is_array($states) ? $states : [], static fn ($state): bool => is_array($state) && in_array($state['state'] ?? null, ['empty', 'filled', 'invalid', 'disabled'], true)));
    // The pictures of the cards (FORM_STEPS §5), the first to the first choice of every card field.
    $shownPictures = array_values(array_filter(is_array($pictures ?? null) ? $pictures : [], static fn ($picture): bool => is_array($picture) && ! empty($picture['url'])));
    $shownFields = array_values(array_filter(is_array($fields) ? $fields : [], static fn ($field): bool => is_array($field) && in_array($field['type'] ?? null, \WebxUi\Widgets\View\Components\Field::TYPES, true) && trim((string) ($field['name'] ?? '')) !== ''));
@endphp
<section @class(['b-showcase-fields', 'b-showcase-fields--narrow' => $width === 'narrow']) data-wx-block="showcase-fields">
    @if ($heading)
        <h2 class="b-showcase-fields__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-fields__note">{{ $note }}</p>
    @endif
    <div class="b-showcase-fields__states">
        @foreach ($shownStates as $state)
            <div class="b-showcase-fields__state" data-state="{{ $state['state'] }}">
                @if (trim((string) ($state['title'] ?? '')) !== '')
                    <h3 class="b-showcase-fields__title">{{ $state['title'] }}</h3>
                @endif
                <div class="b-showcase-fields__list">
                    @foreach ($shownFields as $field)
                        @php
                            $type = $field['type'];
                            $lines = array_values(array_filter(array_map('trim', preg_split('/\R/', (string) ($field['choices'] ?? '')) ?: []), static fn (string $line): bool => $line !== ''));
                            $cards = ($field['view'] ?? 'list') === 'cards' && in_array($type, ['radio', 'checkbox'], true);
                            $choices = [];
                            foreach ($lines as $i => $line) {
                                if (! $cards) {
                                    $choices[(string) ($i + 1)] = $line;
                                    continue;
                                }
                                [$title, $text] = array_pad(array_map('trim', explode('|', $line, 2)), 2, null);
                                $picture = $shownPictures[$i] ?? null;
                                $choices[] = ['value' => (string) ($i + 1), 'label' => $title, 'description' => $text, 'image' => $picture === null ? null : ['src' => $picture['url'], 'width' => $picture['width'] ?? null, 'height' => $picture['height'] ?? null]];
                            }
                            $filled = $state['state'] === 'filled' || $state['state'] === 'disabled';
                            $sample = trim((string) ($field['value'] ?? ''));
                        @endphp
                        @if (! in_array($type, ['select', 'radio'], true) || $choices !== [])
                            <x-webx-field
                                :type="$type"
                                :name="$state['state'].'-'.$set.'.'.trim((string) $field['name'])"
                                :label="(string) ($field['label'] ?? '')"
                                :hint="(string) ($field['hint'] ?? '')"
                                :choices="$type === 'checkbox' || $type === 'select' || $type === 'radio' ? $choices : []"
                                :multiple="(bool) ($field['multiple'] ?? false)"
                                :value="$filled && $sample !== '' ? ($type === 'checkbox' && $choices !== [] ? explode(',', $sample) : $sample) : null"
                                :checked="$filled && $sample !== ''"
                                :error="$state['state'] === 'invalid' ? (string) ($field['error'] ?? '') : null"
                                :disabled="$state['state'] === 'disabled'"
                                :required="(bool) ($field['required'] ?? false)"
                                :optional="! ($field['required'] ?? false)"
                                :inline="(bool) ($field['inline'] ?? false)"
                                :view="$cards ? 'cards' : 'list'"
                                :columns="$cards && is_numeric($field['columns'] ?? null) ? (int) $field['columns'] : null"
                                :autocomplete="trim((string) ($field['autocomplete'] ?? '')) !== '' ? trim((string) $field['autocomplete']) : null"
                            />
                        @endif
                    @endforeach
                </div>
            </div>
        @endforeach
    </div>
</section>

styles:
.b-showcase-fields {
    container-type: inline-size;
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-fields__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-fields__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-fields__states {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--site-space-6);
}

.b-showcase-fields__title {
    margin: 0 0 var(--site-space-3);
    font-size: var(--site-font-size-4);
}

.b-showcase-fields__list {
    display: grid;
    gap: var(--site-space-4);
}

/* A column as narrow as a sidebar's: long words have to break inside it. */
.b-showcase-fields--narrow .b-showcase-fields__states {
    max-width: 20rem;
    padding: var(--site-space-3);
    border: 1px dashed var(--site-color-border);
}

/* Two states side by side where the page has the room for two forms. */
@container (min-width: 64rem) {
    .b-showcase-fields__states {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .b-showcase-fields--narrow .b-showcase-fields__states {
        grid-template-columns: minmax(0, 1fr);
    }
}
